<?php use App\Core\Security;?><h4>مدیریت صف قیمت</h4><div class="table-responsive"><table class="table table-bordered align-middle"><thead><tr><th>امتیاز</th><th>محصول</th><th>مسئول</th><th>وضعیت</th><th>یادداشت</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><form method="post" action="/pricing/public/admin/queue/<?= (int)$r['id']?>"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><td><?=number_format((float)$r['score'],0)?><br><small><?=Security::e($r['priority_level'])?></small></td><td><?=Security::e($r['product_code'])?><br><?=Security::e($r['product_name'])?></td><td><select name="assigned_to" class="form-select form-select-sm"><option value="0">بدون مسئول</option><?php foreach($users as $u):?><option value="<?=(int)$u['id']?>" <?=((int)$r['assigned_to']===(int)$u['id'])?'selected':''?>><?=Security::e($u['name'])?></option><?php endforeach;?></select></td><td><select name="status" class="form-select form-select-sm"><?php foreach(['new'=>'جدید','in_progress'=>'در حال بررسی','needs_followup'=>'نیازمند پیگیری','completed'=>'تکمیل‌شده'] as $k=>$v):?><option value="<?=$k?>" <?=$r['status']===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></td><td><input name="result_note" value="<?=Security::e($r['result_note'])?>" class="form-control form-control-sm"></td><td><button class="btn btn-sm btn-primary">ذخیره</button></td></form></tr><?php endforeach;?></tbody></table></div>